/** Every message sent with status, provider id, cost, read time. */
export const notifications = pgTable('notifications', {
  id: char('id', { length: 26 }).primaryKey(),
  schoolId: char('school_id', { length: 26 }).notNull(),
  recipientUserId: char('recipient_user_id', { length: 26 }),
  recipientAddress: varchar('recipient_address', { length: 160 }),
  channel: varchar('channel', { length: 40, enum: ['sms', 'email', 'push', 'whatsapp', 'in_app', 'voice'] }).notNull(),
  eventKey: varchar('event_key', { length: 80 }),
  templateId: char('template_id', { length: 26 }),
  title: varchar('title', { length: 200 }),
  body: text('body').notNull(),
  data: jsonb('data'),
  entityType: varchar('entity_type', { length: 60 }),
  entityId: char('entity_id', { length: 26 }),
  status: varchar('status', { length: 40, enum: ['queued', 'sent', 'delivered', 'failed', 'read'] }).notNull(),
  providerId: char('provider_id', { length: 26 }),
  providerMsgId: varchar('provider_msg_id', { length: 120 }),
  cost: numeric('cost', { precision: 10, scale: 4 }),
  attempts: smallint('attempts').notNull(),
  error: varchar('error', { length: 255 }),
  scheduledFor: timestamp('scheduled_for', { mode: 'string', precision: 3 }).notNull(),
  sentAt: timestamp('sent_at', { mode: 'string', precision: 3 }),
  deliveredAt: timestamp('delivered_at', { mode: 'string', precision: 3 }),
  readAt: timestamp('read_at', { mode: 'string', precision: 3 }),
  createdAt: timestamp('created_at', { mode: 'string', precision: 3 }).notNull(),
  updatedAt: timestamp('updated_at', { mode: 'string', precision: 3 }).notNull(),
}, (t) => [
  index('ix_notifications_status_scheduled_for'.slice(0, 63)).on(t.status, t.scheduledFor),
  index('ix_notifications_recipient_user_id_created_at'.slice(0, 63)).on(t.recipientUserId, t.createdAt),
  index('ix_notifications_entity_type_entity_id'.slice(0, 63)).on(t.entityType, t.entityId),
]);

